// PTP_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module PTP_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [7:0] c_cfg_inc_ns,
  input logic [31:0] c_cfg_inc_frac,
  input logic [47:0] c_set_sec,
  input logic [29:0] c_set_ns,
  input logic [31:0] c_step_ns,
  input logic  c_time_set,
  input logic  c_time_step,
  input logic  c_snap,
  input logic  c_target_arm,
  input logic  c_target_disarm,
  input logic [47:0] c_snap_sec,
  input logic [29:0] c_snap_ns,
  input logic  c_pps_en,
  input logic [29:0] c_pps_width_ns,
  input logic [47:0] c_target_sec,
  input logic [29:0] c_target_ns,
  input logic [47:0] c_evt_sec,
  input logic [29:0] c_evt_ns,
  input logic  c_cfg_l2_en,
  input logic  c_cfg_ipv4_en,
  input logic  c_cfg_ipv6_en,
  input logic [15:0] c_cfg_rx_lat_ns,
  input logic [15:0] c_cfg_tx_lat_ns,
  input logic  c_target_armed,
  input logic [3:0] c_rxq_type,
  input logic [7:0] c_rxq_domain,
  input logic [15:0] c_rxq_seq,
  input logic [47:0] c_rxq_sec,
  input logic [29:0] c_rxq_ns,
  input logic [3:0] c_txq_type,
  input logic [7:0] c_txq_domain,
  input logic [15:0] c_txq_seq,
  input logic [47:0] c_txq_sec,
  input logic [29:0] c_txq_ns,
  input logic  c_rxq_valid,
  input logic  c_rxq_pop,
  input logic  c_txq_valid,
  input logic  c_txq_pop,
  input logic  c_sec_tick,
  input logic  c_target_hit,
  input logic  c_evt_valid,
  input logic  c_rxq_ovf,
  input logic  c_txq_ovf
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 33;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:32];          // model of every stored word
  logic [6:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_RXTS;          // full / valid pulse / available
  logic m_state_TXTS;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_sec_tick) m_set[0] = 1'b1;
    if (c_target_hit) m_set[1] = 1'b1;
    if (c_evt_valid) m_set[2] = 1'b1;
    if (c_rxq_ovf) m_set[3] = 1'b1;
    if (c_txq_ovf) m_set[4] = 1'b1;
    if (c_rxq_valid && !m_state_RXTS) m_set[5] = 1'b1;
    if (c_rxq_valid && m_state_RXTS && (m_rd && m_map && m_idx == 28)) m_set[5] = 1'b1;
    if (c_txq_valid && !m_state_TXTS) m_set[6] = 1'b1;
    if (c_txq_valid && m_state_TXTS && (m_rd && m_map && m_idx == 32)) m_set[6] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h8;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h7;
      m_w[23] <= 32'h0;
      m_w[24] <= 32'h0;
      m_w[25] <= 32'h0;
      m_w[26] <= 32'h0;
      m_w[27] <= 32'h0;
      m_w[28] <= 32'h0;
      m_w[29] <= 32'h0;
      m_w[30] <= 32'h0;
      m_w[31] <= 32'h0;
      m_w[32] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_RXTS <= 0;
      m_state_TXTS <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h7F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'h3FFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 11) ? PWDATA & m_be & 32'h1F : 0;
      if (m_wr && m_map && m_idx == 15) m_w[15] <= ((m_w[15] & ~m_be) | (PWDATA & m_be)) & 32'h7FFFFFFF;
      if (m_wr && m_map && m_idx == 16) m_w[16] <= ((m_w[16] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 17) m_w[17] <= ((m_w[17] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 18) m_w[18] <= ((m_w[18] & ~m_be) | (PWDATA & m_be)) & 32'h3FFFFFFF;
      if (m_wr && m_map && m_idx == 22) m_w[22] <= ((m_w[22] & ~m_be) | (PWDATA & m_be)) & 32'h7;
      if (m_wr && m_map && m_idx == 23) m_w[23] <= ((m_w[23] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (c_rxq_valid && (!m_state_RXTS || (m_rd && m_map && m_idx == 28))) begin
        m_w[25] <= (32'(c_rxq_type[3:0]) << 0) | (32'(c_rxq_domain[7:0]) << 4) | (32'(c_rxq_seq[15:0]) << 12);
        m_w[26] <= (32'(c_rxq_sec[31:0]) << 0);
        m_w[27] <= (32'(c_rxq_sec[47:32]) << 0);
        m_w[28] <= (32'(c_rxq_ns[29:0]) << 0);
        m_state_RXTS <= 1;
      end else if ((m_rd && m_map && m_idx == 28)) m_state_RXTS <= 0;
      if (c_txq_valid && (!m_state_TXTS || (m_rd && m_map && m_idx == 32))) begin
        m_w[29] <= (32'(c_txq_type[3:0]) << 0) | (32'(c_txq_domain[7:0]) << 4) | (32'(c_txq_seq[15:0]) << 12);
        m_w[30] <= (32'(c_txq_sec[31:0]) << 0);
        m_w[31] <= (32'(c_txq_sec[47:32]) << 0);
        m_w[32] <= (32'(c_txq_ns[29:0]) << 0);
        m_state_TXTS <= 1;
      end else if ((m_rd && m_map && m_idx == 32)) m_state_TXTS <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h50540100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_TXTS, m_state_RXTS});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return 0;
      12: return (32'(c_snap_sec[31:0]) << 0);
      13: return (32'(c_snap_sec[47:32]) << 0);
      14: return (32'(c_snap_ns) << 0);
      15: return m_w[15];
      16: return m_w[16];
      17: return m_w[17];
      18: return m_w[18];
      19: return (32'(c_evt_sec[31:0]) << 0);
      20: return (32'(c_evt_sec[47:32]) << 0);
      21: return (32'(c_evt_ns) << 0);
      22: return m_w[22];
      23: return m_w[23];
      24: return (32'(c_target_armed) << 0);
      25: return m_w[25];
      26: return m_w[26];
      27: return m_w[27];
      28: return m_w[28];
      29: return m_w[29];
      30: return m_w[30];
      31: return m_w[31];
      32: return m_w[32];
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][6:0] & m_w[2][6:0]))
  `SVA_INV(a_core_cfg_inc_ns, c_cfg_inc_ns == m_w[5][7:0])
  `SVA_INV(a_core_cfg_inc_frac, c_cfg_inc_frac == m_w[6][31:0])
  `SVA_INV(a_core_set_sec_31_0, c_set_sec[31:0] == m_w[7][31:0])
  `SVA_INV(a_core_set_sec_47_32, c_set_sec[47:32] == m_w[8][15:0])
  `SVA_INV(a_core_set_ns, c_set_ns == m_w[9][29:0])
  `SVA_INV(a_core_step_ns, c_step_ns == m_w[10][31:0])
  `SVA_INV(a_core_time_set, c_time_set == m_pulse_CMD[0])
  `SVA_INV(a_core_time_step, c_time_step == m_pulse_CMD[1])
  `SVA_INV(a_core_snap, c_snap == m_pulse_CMD[2])
  `SVA_INV(a_core_target_arm, c_target_arm == m_pulse_CMD[3])
  `SVA_INV(a_core_target_disarm, c_target_disarm == m_pulse_CMD[4])
  `SVA_INV(a_core_pps_en, c_pps_en == m_w[15][0:0])
  `SVA_INV(a_core_pps_width_ns, c_pps_width_ns == m_w[15][30:1])
  `SVA_INV(a_core_target_sec_31_0, c_target_sec[31:0] == m_w[16][31:0])
  `SVA_INV(a_core_target_sec_47_32, c_target_sec[47:32] == m_w[17][15:0])
  `SVA_INV(a_core_target_ns, c_target_ns == m_w[18][29:0])
  `SVA_INV(a_core_cfg_l2_en, c_cfg_l2_en == m_w[22][0:0])
  `SVA_INV(a_core_cfg_ipv4_en, c_cfg_ipv4_en == m_w[22][1:1])
  `SVA_INV(a_core_cfg_ipv6_en, c_cfg_ipv6_en == m_w[22][2:2])
  `SVA_INV(a_core_cfg_rx_lat_ns, c_cfg_rx_lat_ns == m_w[23][15:0])
  `SVA_INV(a_core_cfg_tx_lat_ns, c_cfg_tx_lat_ns == m_w[23][31:16])
  `SVA_INV(a_core_rxq_pop, c_rxq_pop == (!m_state_RXTS || (m_rd && m_map && m_idx == 28)))
  `SVA_INV(a_core_txq_pop, c_txq_pop == (!m_state_TXTS || (m_rd && m_map && m_idx == 32)))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_inc_ns == 8'h8 && c_cfg_inc_frac == 32'h0 && c_set_sec[31:0] == 32'h0 && c_set_sec[47:32] == 16'h0 && c_set_ns == 30'h0 && c_step_ns == 32'h0 && c_time_set == 1'h0 && c_time_step == 1'h0 && c_snap == 1'h0 && c_target_arm == 1'h0 && c_target_disarm == 1'h0 && c_pps_en == 1'h0 && c_pps_width_ns == 30'h0 && c_target_sec[31:0] == 32'h0 && c_target_sec[47:32] == 16'h0 && c_target_ns == 30'h0 && c_cfg_l2_en == 1'h1 && c_cfg_ipv4_en == 1'h1 && c_cfg_ipv6_en == 1'h1 && c_cfg_rx_lat_ns == 16'h0 && c_cfg_tx_lat_ns == 16'h0 && c_rxq_pop && c_txq_pop)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_INC, m_rd && m_map && m_idx == 5)
  `FC(wr_INC, m_wr && m_map && m_idx == 5)
  `FC(rd_INC_FRAC, m_rd && m_map && m_idx == 6)
  `FC(wr_INC_FRAC, m_wr && m_map && m_idx == 6)
  `FC(rd_SET0, m_rd && m_map && m_idx == 7)
  `FC(wr_SET0, m_wr && m_map && m_idx == 7)
  `FC(rd_SET1, m_rd && m_map && m_idx == 8)
  `FC(wr_SET1, m_wr && m_map && m_idx == 8)
  `FC(rd_SET2, m_rd && m_map && m_idx == 9)
  `FC(wr_SET2, m_wr && m_map && m_idx == 9)
  `FC(rd_STEP, m_rd && m_map && m_idx == 10)
  `FC(wr_STEP, m_wr && m_map && m_idx == 10)
  `FC(rd_CMD, m_rd && m_map && m_idx == 11)
  `FC(wr_CMD, m_wr && m_map && m_idx == 11)
  `FC(rd_SNAP0, m_rd && m_map && m_idx == 12)
  `FC(wr_SNAP0, m_wr && m_map && m_idx == 12)
  `FC(rd_SNAP1, m_rd && m_map && m_idx == 13)
  `FC(wr_SNAP1, m_wr && m_map && m_idx == 13)
  `FC(rd_SNAP2, m_rd && m_map && m_idx == 14)
  `FC(wr_SNAP2, m_wr && m_map && m_idx == 14)
  `FC(rd_PPS, m_rd && m_map && m_idx == 15)
  `FC(wr_PPS, m_wr && m_map && m_idx == 15)
  `FC(rd_TARGET0, m_rd && m_map && m_idx == 16)
  `FC(wr_TARGET0, m_wr && m_map && m_idx == 16)
  `FC(rd_TARGET1, m_rd && m_map && m_idx == 17)
  `FC(wr_TARGET1, m_wr && m_map && m_idx == 17)
  `FC(rd_TARGET2, m_rd && m_map && m_idx == 18)
  `FC(wr_TARGET2, m_wr && m_map && m_idx == 18)
  `FC(rd_EVT0, m_rd && m_map && m_idx == 19)
  `FC(wr_EVT0, m_wr && m_map && m_idx == 19)
  `FC(rd_EVT1, m_rd && m_map && m_idx == 20)
  `FC(wr_EVT1, m_wr && m_map && m_idx == 20)
  `FC(rd_EVT2, m_rd && m_map && m_idx == 21)
  `FC(wr_EVT2, m_wr && m_map && m_idx == 21)
  `FC(rd_TSU_CFG, m_rd && m_map && m_idx == 22)
  `FC(wr_TSU_CFG, m_wr && m_map && m_idx == 22)
  `FC(rd_LAT, m_rd && m_map && m_idx == 23)
  `FC(wr_LAT, m_wr && m_map && m_idx == 23)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 24)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 24)
  `FC(rd_RXTS0, m_rd && m_map && m_idx == 25)
  `FC(wr_RXTS0, m_wr && m_map && m_idx == 25)
  `FC(rd_RXTS1, m_rd && m_map && m_idx == 26)
  `FC(wr_RXTS1, m_wr && m_map && m_idx == 26)
  `FC(rd_RXTS2, m_rd && m_map && m_idx == 27)
  `FC(wr_RXTS2, m_wr && m_map && m_idx == 27)
  `FC(rd_RXTS3, m_rd && m_map && m_idx == 28)
  `FC(wr_RXTS3, m_wr && m_map && m_idx == 28)
  `FC(rd_TXTS0, m_rd && m_map && m_idx == 29)
  `FC(wr_TXTS0, m_wr && m_map && m_idx == 29)
  `FC(rd_TXTS1, m_rd && m_map && m_idx == 30)
  `FC(wr_TXTS1, m_wr && m_map && m_idx == 30)
  `FC(rd_TXTS2, m_rd && m_map && m_idx == 31)
  `FC(wr_TXTS2, m_wr && m_map && m_idx == 31)
  `FC(rd_TXTS3, m_rd && m_map && m_idx == 32)
  `FC(wr_TXTS3, m_wr && m_map && m_idx == 32)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_SEC_TICK_set, m_set[0])
  `FC(irq_SEC_TICK_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_SEC_TICK_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_SEC_TICK_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_TARGET_set, m_set[1])
  `FC(irq_TARGET_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_TARGET_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_TARGET_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_EVENT_set, m_set[2])
  `FC(irq_EVENT_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_EVENT_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_EVENT_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_RX_OVF_set, m_set[3])
  `FC(irq_RX_OVF_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_RX_OVF_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_RX_OVF_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_TX_OVF_set, m_set[4])
  `FC(irq_TX_OVF_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_TX_OVF_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_TX_OVF_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_RXTS_AVAIL_set, m_set[5])
  `FC(irq_RXTS_AVAIL_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_RXTS_AVAIL_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_RXTS_AVAIL_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_TXTS_AVAIL_set, m_set[6])
  `FC(irq_TXTS_AVAIL_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
